  date, account_id, kind, store, item, category, subcategory, amount_minor,
  source, transfer_id
)
SELECT
  date('now', '-8 days'),
  a.id,
  'transfer_in',
  NULL,
  'Card payment (in)',
  'Transfers',
  NULL,
  15000,
  'manual',
  (SELECT MAX(id) FROM transfers)
FROM accounts a
WHERE a.name = 'Everyday Card' AND a.owner = 'Household'
  AND EXISTS (SELECT 1 FROM settings WHERE key = 'setup_demo_seed' AND value = '1')
  AND NOT EXISTS (
    SELECT 1 FROM operations
    WHERE item = 'Card payment (in)' AND kind = 'transfer_in'
  );
